func noteIcon(level string) string {
	switch level {
	case "ok":
		return "circle-check"
	case "warn":
		return "triangle-alert"
	case "skip":
		return "ban"
	}
	return "info"
}

func noteTone(level string) string {
	switch level {
	case "ok":
		return "text-success"
	case "warn":
		return "text-warning"
	case "skip":
		return "text-danger"
	}
	return "text-muted"
}

func composeKindBadge(kind string) string {
	switch kind {
	case "template":
		return "tuc-badge is-success"
	case "git":
		return "tuc-badge is-info"
	case "skip":
		return "tuc-badge is-danger"
	}
	return "tuc-badge"
}

func slugOrDash(s string) string {
	if s == "" {
		return "—"
	}
	return s
}

